以 TOS Vector 的 tagResource 接口为例，该接口并不像常规接口那样直接透传参数，而是要求将 region、accountId 和 vectorBucketName 组合成特定格式的 resourceTrn 路径参数。

模板实现

```
exportasyncfunctiontagResource(  this: TosVectorsClient,  input: TagResourceInput) {  const { vectorBucketName, tags, accountID } = input; 
  const res = awaitthis.fetchVectors<TagResourceOutput>(    'POST',    `/TagResource`,    {},    {},    // ❌ 直接传递 vectorBucketName    {       tags,      vectorBucketName,     },    { bucket: input.vectorBucketName, accountId: input.accountID }  ); 
  res.data = {};  return res;}
```

AI Agent 实现

```
exportasyncfunctiontagResource(  this: TosVectorsClient,  input: TagResourceInput) {  const { vectorBucketName, tags, accountID } = input;    // ✅ 理解业务语义，拼接 resourceTrn  const resourceTrn = `trn:tosvectors:${this.opts.region}:${accountID}:bucket/${vectorBucketName}`; 
  const res = awaitthis.fetchVectors<TagResourceOutput>(    'POST',    `/tags/${resourceTrn}`,    {},    {},    { tags },    { bucket: input.vectorBucketName, accountId: input.accountID }  ); 
  res.data = {};  return res;}
```

传统生成器只能进行机械的参数映射，无法理解这种隐性的业务规则。
